<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request} from './api';
const data=ref<any>(null),error=ref('');async function load(){error.value='';try{data.value=await request('/dashboard');}catch(e){error.value=(e as Error).message;}}onMounted(load);
</script>
<template><h1>대시보드</h1><p class="muted">게임 데이터와 관리자 작업의 현재 상태를 확인합니다.</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button @click="load">새로고침</el-button><template v-if="data"><div class="stats"><el-card class="stat">게스트<strong>{{data.guests}}</strong></el-card><el-card class="stat">프로필<strong>{{data.profiles}}</strong></el-card><el-card class="stat">경기<strong>{{data.matches}}</strong></el-card></div><el-card><h2>연결 상태</h2><p>PostgreSQL: <el-tag>{{data.db_status==='ok'?'연결됨':'연결 안 됨'}}</el-tag> 게임 API: <el-tag>{{data.game_api_status==='ok'?'연결됨':'연결 안 됨'}}</el-tag></p></el-card><div class="grid"><section><h2>최근 경기</h2><el-table :data="data.recent_matches"><el-table-column prop="match_id" label="경기 ID"/><el-table-column prop="status" label="상태"/><el-table-column prop="created_at" label="시작 시각"/></el-table><router-link to="/matches">경기 전체 보기</router-link></section><section><h2>최근 관리자 작업</h2><el-table :data="data.recent_actions"><el-table-column prop="action" label="작업"/><el-table-column prop="target_id" label="대상"/><el-table-column prop="created_at" label="시각"/></el-table><router-link to="/audit">작업 전체 보기</router-link></section></div></template></template>
